int x = 42;

// Object: reference on stack, object on heap
Wizard w = new Wizard("Lyria", 100);

int a = 10;
int b = a;  // independent copy
b = 99;
System.out.println(a); // 10 — unaffected

int[] arr1 = {1, 2, 3};
int[] arr2 = arr1; // both point to the same array!
arr2[0] = 99;
System.out.println(arr1[0]); // 99 — arr1 also changed!

